import { Component, input } from '@angular/core';

/** Lucide icon from /icons.svg (generated by `npm run icons`). Size follows the surrounding font-size. */
@Component({
  selector: 'app-icon',
  host: { style: 'display:inline-flex;align-items:center;justify-content:center' },
  template: `<svg class="icon" aria-hidden="true" focusable="false"><use [attr.href]="'icons.svg#' + name()" /></svg>`,
})
export class IconComponent {
  readonly name = input.required<string>();
}
